document.addEventListener('submit',async e=>{if(e.target.id==='note-form'){e.preventDefault();const text=String(new FormData(e.target).get('note')).trim();if(!text){toast('先写下一句话或一个链接');return;}state().notes.push({id:uid(),text,createdAt:Date.now()});persist(true);render();toast('灵感已保存');}if(e.target.id==='chat-form'){e.preventDefault();const message=String(new FormData(e.target).get('message'));if(!ui.aiBusy)sendChat(message);}if(e.target.id==='modal-form'){e.preventDefault();const handler=modalSubmit;if(handler)await handler(new FormData(e.target));}});
document.addEventListener('input',e=>{if(e.target.id==='cover-draft'){task().coverDraft=e.target.value;persist(true);}if(e.target.matches('#chat-form textarea'))ui.chatDrafts[task().id]=e.target.value;if(e.target.dataset.taskField){const t=task(),key=e.target.dataset.taskField;const changed=changeContent(t,key,e.target.value);if(changed)refreshReviewSummary();if(key==='script'){const meta=document.querySelector('.editor-meta>span');if(meta)meta.innerHTML='正在打磨 · <span id="word-count">'+t.script.length+'</span> 字';}const count=document.querySelector('#word-count');if(count)count.textContent=t.script.length;if(key==='script'){const action=document.querySelector('.editor-bottom .btn.primary');if(action){action.dataset.action=t.script.trim()?'finalize':host?.codex?'generate-script':'demo-script';action.innerHTML=icon(t.script.trim()?'check':'spark')+(t.script.trim()?'确认定稿':host?.codex?'请 Codex 起草口播稿':'生成示例初稿');}}const saved=document.querySelector('#save-status');if(saved)saved.textContent='正在保存…';clearTimeout(saveTimeout);if(host){const ok=persist(true);if(saved?.isConnected)saved.textContent=ok?savedLabel:'保存未完成，请导出备份';}else saveTimeout=setTimeout(()=>{const ok=persist(true);if(saved?.isConnected)saved.textContent=ok?savedLabel:'保存未完成，请导出备份';},500);}if(e.target.id==='topic-search'){ui.search=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#topic-search');input.focus();input.setSelectionRange(start,start);}});
document.addEventListener('input',e=>{if(e.target.id==='repository-search'){ui.repositorySearch=e.target.value;const start=e.target.selectionStart;render();const input=document.querySelector('#repository-search');input.focus();input.setSelectionRange(start,start);}});
