document.addEventListener('change',e=>{videoFlow.change(e);if(e.target.id==='cover-reference-file'||e.target.id==='cover-import-file'){void covers.choose(e.target.files[0],e.target.id==='cover-reference-file');e.target.value='';}if(e.target.id==='overview-days'){ui.overviewDays=Number(e.target.value);render();}const s=state(),t=task();if(e.target.id==='reminder-tests'){ui.reminderTests=e.target.checked;refreshReminders(true);}if(e.target.id==='sampling-task'){ui.samplingTaskId=e.target.value;render();}if(e.target.id==='sampling-tests'){ui.includeSamplingTests=e.target.checked;render();}if(e.target.id==='include-example-assets'){ui.includeExampleAssets=e.target.checked;render();}if(e.target.name==='selected-topic'){s.selectedTopicId=e.target.value;persist(true);render();}if(e.target.id==='task-select'){s.activeTaskId=e.target.value;persist(true);render();}if(e.target.id==='task-status'){try{const result=saveTaskChange(t,()=>changeProgress(s,t,e.target.value),persist);e.target.value=t.status;if(result==='publication')publish();else{render();toast('创作进度已更新');}}catch(err){e.target.value=t.status;toast(err.message);}}if(e.target.id==='film-ready'||e.target.id==='facts-ready'){if(e.target.id==='facts-ready'&&e.target.checked){try{confirmReview(t,'publish');}catch(err){e.target.checked=false;toast(err.message);return;}refreshReviewSummary();}t[e.target.id==='film-ready'?'filmReady':'factsReady']=e.target.checked;persist(true);}if(e.target.dataset.todo){const todo=s.todos.find(x=>x.id===e.target.dataset.todo);todo.done=e.target.checked;persist(true);render();toast('改进待办已完成');}if(e.target.id==='reduced-setting'){s.settings.reduced=e.target.checked;persist(true);applyMotion();}if(e.target.id==='failure-setting'){s.settings.simulateFailure=e.target.checked;persist(true);}if(e.target.id==='video-file'){void videoFlow.choose(e.target.files[0]);e.target.value='';}if(e.target.id==='review-image'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){error('请选择图片文件');return;}if(reviewImageUrl)URL.revokeObjectURL(reviewImageUrl);reviewImageUrl=URL.createObjectURL(file);const img=document.querySelector('#review-image-preview');img.src=reviewImageUrl;img.classList.remove('hidden');}});
addEventListener('pagehide',()=>{clearTimeout(saveTimeout);store.save();});

