function changeAssistantMode(mode){if(!['docked','expanded','collapsed'].includes(mode))return;ui.assistantMode=mode;render();const action=mode==='collapsed'?'.assistant-reopen [data-value="expanded"]':'.assistant-toolbar [data-action="assistant-mode"]';if(!ui.chatSelection||mode==='collapsed')document.querySelector(action)?.focus({preventScroll:true});}
function renderWritingPanel(){if(route==='studio'&&task().stage===3){const area=document.querySelector('.title-workflow');if(area)area.outerHTML=titlePanel(task(),ui);}if(route!=='studio'||!['ai','assets'].includes(ui.studioTab))return;const content=document.querySelector('.assistant-content');if(!content)return;rememberAssistant(ui);content.innerHTML=ui.studioTab==='assets'?assetsPanel(task(),state().assets,ui):writingPanel(task(),ui,state().assets);restoreAssistant(ui);}
async function checkCodex(){if(!host?.codex||ui.codexChecking)return;ui.codexChecking=true;renderWritingPanel();try{ui.codexStatus=await host.codex.status();}catch(err){ui.codexStatus={available:false,message:err.message};}finally{ui.codexChecking=false;renderWritingPanel();}}
async function sendCodex(message,kind='chat',clearDraft=false,metadata=null){const t=task();message=message.trim();if(!host?.codex)return toast('请在 Obsidian 中使用真实观点共创');if(!message)return;if(aiPending(t.aiJob))return toast('当前生成尚未结束，可以等待或取消');try{const previous=t.messages.find(m=>m.role==='user'&&m.jobId===t.aiJob?.id);if(previous)previous.status=t.aiJob.status;const prompt=writingPrompt(t,state().assets,message,kind,metadata);const job=host.codex.start(t.id,prompt);t.messages.push({role:'user',text:message,provider:'codex',jobId:job.id,createdAt:Date.now(),kind,...(kind==='viewpoints'?{sourceContext:directionContext(t)}:kind==='assets'?{sourceContext:metadata.sourceContext,assetCatalog:metadata.catalog,examples:metadata.examples}:kind==='titles'?{titleBasis:metadata}:{})});t.aiJob=job;if(kind==='titles')t.titleRequirements=metadata.requirements;if(clearDraft)ui.chatDrafts[t.id]='';ui.studioTab='ai';if(['viewpoints','assets','titles'].includes(kind))ui.assistantMode='expanded';if(!persist(true))await host.codex.cancel(job.id);render();}catch(err){toast(err.message);}}
async function cancelCodex(){const t=task();if(!aiPending(t.aiJob))return;const result=await host.codex.cancel(t.aiJob.id);if(result){acceptJob(t,result);persist(true);renderWritingPanel();}}
function adoptCodex(id){const t=task(),m=t.messages.find(x=>x.role==='assistant'&&x.jobId===id);if(!m)return;openModal('选择并采用内容',`<p>请保留需要采用的部分。保存后仍需在对应步骤确认。</p><label class="field">采用到<select name="field"><option value="viewpoint">核心观点</option><option value="outline">提纲</option><option value="script">口播稿</option><option value="finalTitle">最终标题</option></select></label>${area('编辑要采用的文字','text',m.text,'required')}<div class="modal-callout">将替换所选字段，修改前的文字会保留在本条共创记录中。不会自动定稿。</div>`,{label:'采用并保留旧内容',submit:data=>{const key=String(data.get('field')),text=String(data.get('text')).trim();if(!['viewpoint','outline','script','finalTitle'].includes(key)||!text)return error('请选择目标并填写内容');if((key==='outline'||key==='script')&&!reliable(t,'viewpoint'))return error('请先确认核心观点');if(key==='script'&&!reliable(t,'outline'))return error('请先确认提纲');t.messages.push({role:'assistant',provider:'local',text:`采用前的${{viewpoint:'核心观点',outline:'提纲',script:'口播稿',finalTitle:'标题'}[key]}：\n${t[key]||'（空）'}`});changeContent(t,key,text);t.stage={viewpoint:0,outline:1,script:2,finalTitle:3}[key];persist(true);closeModal();render();}});}
if(host?.codex)setInterval(()=>{let changed=false;for(const t of state().tasks){if(!aiPending(t.aiJob))continue;const result=host.codex.get(t.aiJob.id)||{id:t.aiJob.id,taskId:t.id,status:'unknown',error:'工作台已重开，本次执行状态待核实。原稿与要求已保留，请检查连接后重新发起。'};if(result.status!==t.aiJob.status){acceptJob(t,result);changed=true;}}if(changed){persist(true);renderWritingPanel();}},750);

function refreshReviewSummary(){const t=task(),region=document.querySelector('#content-review-summary');if(region)region.innerHTML=reviewBanner(t);document.querySelectorAll('.stage-nav button').forEach((button,i)=>{if(i<3)button.querySelector('span').innerHTML=reliable(t,['viewpoint','outline','script'][i])?icon('check'):String(i+1).padStart(2,'0');});}
function showContentReview(key){
 const t=task(),keys=key==='all'?pendingReviews(t):[key];if(!keys.length||keys.some(k=>!Object.hasOwn(reviewNames,k)||!needsReview(t,k)))return;
 const excerpts=keys.map(k=>{const text=k==='assets'?state().assets.filter(a=>t.assetIds.includes(a.id)).map(a=>a.name+'：'+a.method).join('\n'):k==='cover'?`当前标题：${t.finalTitle||t.title}。请核对下方保留的封面是否仍然适用。`:k==='publish'?'请重新核对事实、来源与成片表达。已记录的发布时间和链接会保留。':t[k];return `<section class="review-excerpt"><h3>${reviewNames[k]}</h3>${reviewDescription(t,k)}<div class="reference-copy">${esc(text||'暂无内容')}</div>${k==='cover'?(finalCover(t)?`<img data-cover-image="${esc(finalCover(t).file.id)}" alt="待复核封面" style="max-width:100%;max-height:600px">`:'<canvas id="review-cover-canvas" width="600" height="800" aria-label="待复核的现有示例封面"></canvas>'):''}</section>`;}).join('');
 openModal(key==='all'?'确认不影响下游':`复核${reviewNames[key]}`,`<p>当前核心观点：${esc(t.viewpoint||'尚未填写')}</p>${excerpts}${key!=='all'?`<button type="button" class="btn secondary small" data-action="review-edit" data-value="${key}">前往检查或修改</button>`:''}<label class="review-ack"><input type="checkbox" name="reviewAck" required>我已对照当前内容，确认以上成果仍然适用</label>`,{wide:true,label:'确认仍适用',submit:data=>{if(!data.get('reviewAck'))return error('请先核对并勾选确认');try{if(key==='all')confirmNoImpact(t);else confirmReview(t,key);}catch(err){return error(err.message);}persist(true);closeModal();render();toast('复核已保存，现有内容保持不变');}});
 const canvas=modal.querySelector('#review-cover-canvas');if(canvas)paintCover(canvas,t);void covers.paint();
}

function showDirection(id,index){
 const t=task(),found=findDirection(t,id,index);if(!found)return toast('没有找到这个观点方向');
 openModal('把这个方向改成你的观点',`<h3>${esc(found.direction.title)}</h3>${directionDetails(found.direction)}${area('我的核心观点','viewpoint',found.direction.claim,'required maxlength="8000"')}${found.stale?'<label class="review-ack"><input type="checkbox" name="changedAck" required>任务内容已有变化，我已重新核对这条候选的依据</label>':''}<p class="micro muted">保存后仍需确认观点。旧观点会保留，相关下游成果会提示复核。</p>`,{wide:true,label:'保存为待确认观点',submit:data=>{try{adoptDirection(t,id,index,String(data.get('viewpoint')),Boolean(data.get('changedAck')));}catch(err){return error(err.message);}persist(true);closeModal();ui.assistantMode='docked';render();document.querySelector('[data-task-field="viewpoint"]')?.focus();toast('已保存候选，请按自己的判断修改并确认观点');}});
}
function discussDirection(id,index){
 const t=task(),found=findDirection(t,id,index);if(!found)return;
 const request=`我想继续讨论「${found.direction.title}」：\n${found.direction.claim}\n请先追问我真实的判断和依据，暂不写稿。`;
 ui.chatDrafts[t.id]=[ui.chatDrafts[t.id],request].filter(Boolean).join('\n\n');ui.studioTab='ai';ui.assistantMode='expanded';render();
 const input=document.querySelector('#chat-form textarea');input?.focus();input?.setSelectionRange(input.value.length,input.value.length);
}

function startTitles(){
 const t=task(),bases=titleBases(t);if(!host?.codex)return toast('请在 Obsidian 中使用真实标题生成');if(!bases.length)return toast('请先补充观点，或复核用于生成标题的内容');
 if(aiPending(t.aiJob))return toast('当前生成尚未结束，可以等待或取消');
 openModal('准备标题候选',`<p>选择本次依据。未确认内容只用于探索；标题仍由你选择和修改。</p><label class="field">标题依据<select name="basis">${bases.map((b,i)=>`<option value="${b.key}" ${i===bases.length-1?'selected':''}>${b.label} · ${b.status}</option>`).join('')}</select></label>${area('标题要求（可选）','requirements',t.titleRequirements||'','maxlength="1000" placeholder="例如：突出具体问题，不使用效果承诺"')}<p class="micro muted">只使用所选内容、当前参考资料和已选资产，不读取外部链接。</p>`,{wide:true,label:'生成候选',submit:data=>{
  let meta;try{meta=titleInput(t,String(data.get('basis')),String(data.get('requirements')));}catch(err){return error(err.message);}
  closeModal();return sendCodex(titleRequest,'titles',false,meta);
 }});
}
function showTitle(id,index){
 const t=task(),found=findTitle(t,id,index);if(!found)return toast('没有找到这条标题候选');if(found.stale)return toast('标题依据已有变化，请重新生成候选');
 const c=found.candidate,b=found.message.titleBasis;
 openModal('修改并采用标题',`<p>依据：${esc(b.basisLabel)} · ${esc(b.basisStatus)}</p><p>表达方向：${esc(c.angle)}</p><div class="modal-callout">内容依据：${esc(c.reason)}<br>使用边界：${esc(c.caution)}</div>${field('最终标题','title',c.title,'text','required maxlength="120"')}<p>当前标题：${esc(t.finalTitle||'尚未填写')}</p><p class="micro muted">采用后保存为当前标题，旧标题保留在共创记录中；已有封面保留并提示复核。</p>`,{wide:true,label:'确认采用标题',submit:data=>{
  try{adoptTitle(t,id,index,String(data.get('title')));}catch(err){return error(err.message);}
  persist(true);closeModal();ui.assistantMode='docked';render();toast(t.cover?'标题已保存，请核对原封面是否仍适用':'标题已保存，可以继续准备封面');
 }});
}

function sampleForm(period,id){
 const t=selectedSamplingTask(state(),ui);if(!t)return toast('请先选择已发布内容');
 const old=id?(state().samples||[]).find(x=>x.id===id&&x.taskId===t.id):null;if(id&&!old)return toast('没有找到采样记录');
 period=old?.period||period;const guard=samplingGuard(state(),t.id),values=Object.fromEntries((old?.metrics||[]).map(m=>[m.key,m.value??'']));let saving=false,recognizer;
 openModal(old?'修改采样并重新核对':'记录'+periodLabel(period)+'数据',`<p>${esc(t.title)}${t.testOnly?' · 测试内容，未真实发布':''}</p><p>采样目标：${periodLabel(period)} · 请填实际采样时间，延迟时不要填回目标时间。</p><div class="sample-verify-layout"><aside><label class="field">原始截图（PNG / JPEG / WebP，最多 8 MB）<input name="screenshot" id="sample-file" type="file" accept="image/png,image/jpeg,image/webp" ${host?.samplingFiles?'':'disabled'}></label><p class="micro">${old?.screenshot?'不重新选择会保留已有原图；更换后旧图仍保留在历史中。':host?.samplingFiles?'截图在确认保存时写入本地知识库；点击识别指标后才进行本地识别。':'截图保存请在 Obsidian 打开；这里可手动登记并说明来源。'}</p><img id="sample-file-preview" class="sample-image hidden" alt="待核对的采样截图"><button type="button" class="btn secondary" data-ocr-zoom>放大原图</button></aside><section><div data-ocr-region class="ocr-region"></div><h3>人工核对后的指标</h3><label class="field">截图中的指标名称<select name="viewsName"><option ${old?.metrics?.[0]?.name==='浏览'?'':'selected'}>播放</option><option ${old?.metrics?.[0]?.name==='浏览'?'selected':''}>浏览</option></select></label><div class="modal-grid">${[['views','浏览 / 播放（次）'],['likes','点赞（次）'],['saves','收藏（次）'],['comments','评论（次）']].map(([k,label])=>field(label,k,values[k]??'','number','min="0" step="1" placeholder="未提供"')).join('')}</div>${field('实际采样时间','sampledAt',old?localDateTime(old.sampledAt):'','datetime-local','required')}${area('数据来源 / 截图缺失原因','sourceNote',old?.sourceNote||'','maxlength="2000" placeholder="未附截图时必填；如测试样本请明确标注"')}<label class="review-ack"><input type="checkbox" name="ack" required>我已核对截图或来源、指标名称和数值、实际采样时间；缺失数据已留空，缩写近似值已核对</label></section></div>`,{wide:true,label:'确认并保存采样',submit:async data=>{
  if(saving||recognizer?.running)return;const form=modal.querySelector('form'),file=data.get('screenshot'),selectedFile=form.querySelector('#sample-file').files[0],hasFile=file&&file.size>0;
  const input={...Object.fromEntries(data),period,ack:Boolean(data.get('ack'))};if(old&&input.sampledAt===localDateTime(old.sampledAt))input.sampledAt=old.sampledAt;
  let attachment=old?.screenshot||null;
  try{
   if(hasFile){if(!host?.samplingFiles)throw Error('截图保存请在 Obsidian 打开');if(file.size>8*1024*1024)throw Error('每张截图请控制在 8 MB 以内');attachment={id:'0'.repeat(64)+'.png',sha256:'0'.repeat(64),path:'06-附件/数据采样/'+'0'.repeat(64)+'.png'};}
   validateSample(state(),t.id,input,attachment,id);if(guard!==samplingGuard(state(),t.id))throw Error('记录已有变化，请重新打开核对');
   saving=true;form.querySelector('[type=submit]').disabled=true;
   if(hasFile){const bitmap=await createImageBitmap(file);bitmap.close();attachment=await host.samplingFiles.save(await file.arrayBuffer(),file.name);}
   if(!form.isConnected||!modal.open)return;
   if(form.querySelector('#sample-file').files[0]!==selectedFile)throw Error('截图已更换，请重新核对后保存');
   if(recognizer.result||old?.recognition)input.recognition=recognizer.result;
   const staged=structuredClone(state()),result=saveContentSample(staged,t.id,input,attachment,id,guard),previous={samples:state().samples,contentReports:state().contentReports};
   state().samples=staged.samples;if(staged.contentReports)state().contentReports=staged.contentReports;
   if(!persist(true)){for(const [key,value] of Object.entries(previous)){if(value===undefined)delete state()[key];else state()[key]=value;}return error('采样记录保存失败，原记录已保留；请保留表单，检查本地存储后重试');}
   closeModal();render();toast(result.changed?'采样已核对保存，原图与历史留在本地':'记录没有变化，已保留原版本');
  }catch(err){error(err.message||'截图无法读取，请检查文件后重试');}finally{saving=false;if(form.isConnected)form.querySelector('[type=submit]').disabled=false;}
 }});
 modal.style.width='min(1120px, calc(100vw - 40px))';
 recognizer=attachScreenshotRecognition({form:modal.querySelector('form'),host,old,onError:error});
}
async function showSampleImage(id,revision){const record=state().samples?.find(x=>x.id===id),x=revision?record?.history?.find(x=>x.revision===Number(revision)):record;if(!x?.screenshot)return toast('这条记录没有原图');if(!host?.samplingFiles)return toast('请在保存截图的 Obsidian 知识库中查看');try{const src=await host.samplingFiles.read(x.screenshot.id);openModal('采样原始截图',`<p>${esc(x.screenshot.name)} · ${x.testOnly?'测试素材':'本地保存原图'}</p><img class="sample-image" src="${esc(src)}" alt="已保存的采样原始截图"><p class="micro">实际采样：${esc(new Date(x.sampledAt).toLocaleString('zh-CN'))} · 版本 ${x.revision}</p>`,{wide:true});}catch(err){toast(err.message);}}

const contentReview=reviewController({state,host,ui,openModal,closeModal,area,field,error,toast,persist,render,route:()=>route});

function refreshReminders(force=false){refreshReminderRegions({document,state:state(),ui,force});}
function openReminder(id,period){try{const row=reminderDestination(state(),id,period),changing=route!=='review';ui.samplingTaskId=id;ui.includeSamplingTests=row.testOnly;ui.reviewMode='content';ui.reminderReportTarget=changing&&row.action==='report';if(changing)go('review');else render();if(row.action==='sample')sampleForm(period);else if(!changing)document.querySelector('.content-ai-reports')?.scrollIntoView({block:'start'});}catch(e){refreshReminders();toast(e.message);}}
setInterval(()=>refreshReminders(),30000);
addEventListener('focus',()=>refreshReminders());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshReminders();});
document.addEventListener('focusout',()=>queueMicrotask(()=>refreshReminders()));
